const DAY = 24 * 60 * 60 * 1000;

describe("Review", () => {
  beforeEach(() => {
    localStorage.clear();
    store.clear();
  });

  it("walks the due queue and returns to the empty state", async () => {
    const a = store.keep({
      phrase_fr: "la machine à café",
      phrase_en: "the coffee machine",
      noun_fr: "machine à café",
      place: "café",
      errorType: "article",
    });
    const b = store.keep({
      phrase_fr: "une tasse, s'il vous plaît",
      phrase_en: "a cup, please",
      noun_fr: "tasse",
      place: "café",
      errorType: "gender",
    });
    const future = store.keep({ phrase_fr: "le sucre", phrase_en: "the sugar", noun_fr: "sucre" });
    store.grade(future.id, 5, Date.now());
    store.grade(a.id, 0, Date.now() - 2 * DAY);
    store.grade(b.id, 0, Date.now() - DAY - 1000);
    // reset reps after the setup grades so the first pass is reps 1
    const cards = store.all().map((c) => (c.id === future.id ? c : { ...c, reps: 0 }));
    localStorage.setItem("alltag.cards", JSON.stringify(cards));

    render(<Review />);
    expect(screen.getByText("due now")).toBeInTheDocument();
    expect(screen.getByTestId("due-count")).toHaveTextContent("2");
    expect(document.querySelector('[data-group="article"]')).not.toBeNull();
    expect(screen.getByText("you keep dropping the article on feminine nouns")).toBeInTheDocument();

    fireEvent.click(screen.getByRole("button", { name: "start" }));
    expect(screen.getByText("say it: the coffee machine")).toBeInTheDocument();

    fireEvent.change(screen.getByLabelText("or type it"), { target: { value: "la machine à café" } });
    fireEvent.click(screen.getByRole("button", { name: "check" }));
    expect(await screen.findByText(/next in 1 day$/)).toBeInTheDocument();
    const graded = store.get(a.id)!;
    expect(graded.reps).toBe(1);
    expect(graded.interval).toBe(1);

    fireEvent.click(screen.getByRole("button", { name: "next" }));
    expect(screen.getByText("say it: a cup, please")).toBeInTheDocument();

    fireEvent.change(screen.getByLabelText("or type it"), { target: { value: "" } });
    fireEvent.click(screen.getByRole("button", { name: "check" }));
    expect(await screen.findByText("not yet, again tomorrow")).toBeInTheDocument();

    fireEvent.click(screen.getByRole("button", { name: "next" }));
    expect(screen.getByText("nothing due, go look at something")).toBeInTheDocument();
  });
});
import { fireEvent, render, screen } from "@testing-library/react";
import * as conversations from "../srs/conversations";
import * as store from "../srs/store";
import Diary from "./Diary";

describe("Diary", () => {
  beforeEach(() => {
    localStorage.clear();
    store.clear();
    conversations.clear();
  });

  it("renders one tile per kept card with phrase and ISO date", () => {
    store.keep({ phrase_fr: "la machine à café", phrase_en: "the coffee machine", noun_fr: "machine", place: "café" });
    store.keep({ phrase_fr: "une tasse", phrase_en: "a cup", noun_fr: "tasse", place: "café" });
    store.keep({ phrase_fr: "un billet", phrase_en: "a ticket", noun_fr: "billet", place: "gare" });

    render(<Diary />);
    expect(screen.getByText("what you can say now")).toBeInTheDocument();
    const tiles = screen.getAllByTestId("diary-tile");
    expect(tiles).toHaveLength(3);
    for (const phrase of ["la machine à café", "une tasse", "un billet"]) {
      expect(screen.getByText(phrase)).toBeInTheDocument();
    }
    for (const tile of tiles) {
      expect(tile.textContent).toMatch(/\d{4}-\d{2}-\d{2}/);
    }
  });

  it("renders the empty state", () => {
    render(<Diary />);
    expect(screen.queryAllByTestId("diary-tile")).toHaveLength(0);
    expect(screen.getByText("nothing kept yet, go look at something")).toBeInTheDocument();
  });

  it("renders a conversation row interleaved by date and expands its lines", () => {
    const old = new Date(2026, 9, 9, 9, 0).getTime();
    vi.spyOn(Date, "now").mockReturnValue(old);
    store.keep({ phrase_fr: "une tasse", phrase_en: "a cup", noun_fr: "tasse", place: "café" });
    vi.restoreAllMocks();
    conversations.save({
      startedAt: new Date(2026, 9, 10, 14, 5).toISOString(),
      durationS: 134,
      lines: [
        { fr: "On se voit demain ?", en: "See you tomorrow?", kept: true },
        { fr: "Oui, à midi.", en: "Yes, at noon.", kept: false },
      ],
    });

    render(<Diary />);
    const row = screen.getByTestId("diary-conversation");
    expect(row.textContent).toContain("conversation, sat 14:05");
    expect(row.textContent).toContain("2 lines, 1 kept");
    // newest first: the conversation comes before the older scene tile
    const tile = screen.getByTestId("diary-tile");
    expect(row.compareDocumentPosition(tile) & Node.DOCUMENT_POSITION_FOLLOWING).toBeTruthy();
    expect(screen.queryByText("Oui, à midi.")).not.toBeInTheDocument();
    fireEvent.click(row.querySelector("button")!);
    expect(screen.getByText("Oui, à midi.")).toBeInTheDocument();
    expect(screen.getByText("See you tomorrow?")).toBeInTheDocument();
  });

  it("filters scenes and conversations with the chips", () => {
    store.keep({ phrase_fr: "une tasse", phrase_en: "a cup", noun_fr: "tasse", place: "café" });
    conversations.save({ startedAt: new Date().toISOString(), durationS: 60, lines: [] });

    render(<Diary />);
    expect(screen.getAllByTestId("diary-tile")).toHaveLength(1);
    expect(screen.getAllByTestId("diary-conversation")).toHaveLength(1);

    fireEvent.click(screen.getByRole("button", { name: "scenes" }));
    expect(screen.getAllByTestId("diary-tile")).toHaveLength(1);
    expect(screen.queryByTestId("diary-conversation")).not.toBeInTheDocument();

    fireEvent.click(screen.getByRole("button", { name: "conversations" }));
    expect(screen.queryByTestId("diary-tile")).not.toBeInTheDocument();
    expect(screen.getAllByTestId("diary-conversation")).toHaveLength(1);
    expect(screen.getByRole("button", { name: "conversations" })).toHaveAttribute("aria-pressed", "true");

    fireEvent.click(screen.getByRole("button", { name: "all" }));
    expect(screen.getAllByTestId("diary-tile")).toHaveLength(1);
    expect(screen.getAllByTestId("diary-conversation")).toHaveLength(1);
  });
});

