  const [filter, setFilter] = useState<Filter>("all");
  const cards = store.all();
  const convs = conversations.all();
  const entries: Entry[] = [
    ...(filter === "conversations" ? [] : cards.map((card): Entry => ({ kind: "scene", at: card.learnedAt, card }))),
    ...(filter === "scenes"
